// Dijital metre: HC-SR04 mesafesini 5 LED'lik çubukta ve seri ekranda gösterir.
const int TRIG_PIN = 12;
const int ECHO_PIN = 11;
const int BUZZER_PIN = 3;
const int LED_SAYISI = 5;
const int LEDLER[LED_SAYISI] = {8, 7, 6, 5, 4};  // soldan sağa: 1. LED ... 5. LED

const int LED_BASI_CM = 20;                // her LED 20 cm gösterir
const int ALARM_CM = 20;                   // bundan yakında buzzer öter
const unsigned long OLCUM_MS = 100;        // ölçüm aralığı
const unsigned long YAZDIR_MS = 500;       // seri ekrana yazma aralığı

long cm = 0;
unsigned long sonOlcum = 0;
unsigned long sonYazdir = 0;
unsigned long sonBip = 0;

// Mesafeyi cm olarak döndürür; yankı gelmezse 0.
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long sure = pulseIn(ECHO_PIN, HIGH, 30000);  // en çok 30 ms bekle (~5 m)
  return sure / 58;
}

// Mesafeye göre kaç LED yanacağını hesaplar ve LED'leri yakar.
void cubukGoster(long mesafe) {
  int yanan = 0;
  if (mesafe > 0) yanan = (mesafe + LED_BASI_CM - 1) / LED_BASI_CM;  // yukarı yuvarla
  if (yanan > LED_SAYISI) yanan = LED_SAYISI;
  for (int i = 0; i < LED_SAYISI; i++) {
    digitalWrite(LEDLER[i], i < yanan ? HIGH : LOW);
  }
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  for (int i = 0; i < LED_SAYISI; i++) pinMode(LEDLER[i], OUTPUT);
  Serial.println("Dijital metre hazir.");
}

void loop() {
  unsigned long simdi = millis();

  if (simdi - sonOlcum >= OLCUM_MS) {
    sonOlcum = simdi;
    cm = mesafeOlc();
    cubukGoster(cm);
  }

  if (simdi - sonYazdir >= YAZDIR_MS) {
    sonYazdir = simdi;
    if (cm > 0) {
      Serial.print("Mesafe: ");
      Serial.print(cm);
      Serial.println(" cm");
    } else {
      Serial.println("Olcum yok");
    }
  }

  // Çok yakında bip: aralık mesafeyle kısalır (5 cm'de 125 ms, 20 cm'de 500 ms).
  if (cm > 0 && cm < ALARM_CM) {
    unsigned long aralik = cm * 25;
    if (aralik < 80) aralik = 80;
    if (simdi - sonBip >= aralik) {
      sonBip = simdi;
      tone(BUZZER_PIN, 2000, 50);
    }
  }
}
